const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const c=await browser.newContext({viewport:{width:1366,height:768}});const p=await c.newPage();const statuses=[],registrationErrors=[];let result='NOT_CONFIRMED';
