 let ready=false;for(let i=0;i<120;i++){for(const frame of p.frames()){if(frame===p.mainFrame())continue;const text=await frame.locator('body').innerText().catch(()=>'');if(/Gartic Phone|THE TELEPHONE GAME|TELEPHONE GAME|nickname/i.test(text)&&text.length>100){ready=true;break;}}if(ready)break;await p.waitForTimeout(250);}
 await p.evaluate(()=>document.fonts.ready);await p.screenshot({path:E+'/11-gartic-public-registration.png',fullPage:true});result=ready&&!registrationErrors.length?'PASS':'NOT_CONFIRMED';await writeFile(E+'/GARTIC_RESULT.json',JSON.stringify({result,scope:'Public landing page only; no game creation, multiplayer participation, external login or gameplay claim.',statuses,registrationErrors},null,2));console.log('GARTIC_PUBLIC_REGISTRATION='+result+'; registrationErrors='+registrationErrors.length);if(result!=='PASS')process.exitCode=1;
